import{_ as o,o as e,c as t,a3 as r}from"./chunks/framework.D1xzioSG.js";const p=JSON.parse('{"title":"演员定位和缩放","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/actor-coordinate-and-scaling.md","filePath":"tutorial/actor-coordinate-and-scaling.md","lastUpdated":1770488356000}'),n={name:"tutorial/actor-coordinate-and-scaling.md"};function c(d,a,i,s,l,_){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="演员定位和缩放" tabindex="-1">演员定位和缩放 <a class="header-anchor" href="#演员定位和缩放" aria-label="Permalink to &quot;演员定位和缩放&quot;">​</a></h1><h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h2><p><code>KND_DialogueCharacter</code> 是 Konado 对话系统中核心的角色定位组件，专为对话场景中演员（角色）的位置管理设计。该组件创新性地采用<strong>屏幕区块分割算法</strong>实现角色位置的精准、自适应定位，同时内置补间动画过渡逻辑，兼顾了定位的灵活性、适配性与视觉体验。</p><p>对话管理器会根据对话内容自动生成 <code>KND_DialogueCharacter</code> 实例，并自动管理。</p><h2 id="演员定位" tabindex="-1">演员定位 <a class="header-anchor" href="#演员定位" aria-label="Permalink to &quot;演员定位&quot;">​</a></h2><p>组件将承载角色的 <code>Control</code> 节点画布容器横向等分为 <code>division</code> 个区块（区块数量可设置≥2），区块索引从<strong>左到右递增</strong>（0 为最左侧，division 为最右侧），</p><p><code>character_position</code>（角色位置索引）的有效范围被限制为 <code>[1, division-1]</code>，避免角色完全贴左/贴右导致的视觉溢出问题，角色的<strong>中心</strong>将对齐区块分割线显示。</p><h2 id="演员缩放" tabindex="-1">演员缩放 <a class="header-anchor" href="#演员缩放" aria-label="Permalink to &quot;演员缩放&quot;">​</a></h2><p>通过调用 <code>set_texture_scale</code> 调整纹理缩放后将同步更新位置，保证缩放后的角色仍对齐目标区块，避免因缩放导致的视觉溢出问题。</p>',9)])])}const u=o(n,[["render",c]]);export{p as __pageData,u as default};
